import { frontend, resetFrontendMocks } from "../support/frontendMocks";
import { cleanup, fireEvent, render, screen, within } from "@testing-library/react";
import { afterEach, beforeEach, expect, test, vi } from "vitest";
import ActiveDaysChart from "../../src/components/home/ActiveDaysChart";
import { SnapshotPeriod } from "../../src/components/home/homeStatistics";
import Theme, { ThemesType } from "../../src/util/Theme";

afterEach(() => { cleanup(); vi.useRealTimers(); });
beforeEach(resetFrontendMocks);

// Generated by Codex and not thoroughly checked for correctness.
test("a rolling week follows the selected dates instead of aligning to Monday", () => {
  render(<ActiveDaysChart
    startTimeSeconds={new Date(2026, 9, 24).getTime() / 1000}
    endTimeSeconds={new Date(2026, 9, 31).getTime() / 1000}
    submissions={[]}
  />);
  const days = screen.getAllByRole("img");
  expect(days).toHaveLength(7);
  expect(days[0].getAttribute("aria-label")).toBe("Sat Oct 24 2026: 0 submissions");
  expect(days[6].getAttribute("aria-label")).toBe("Fri Oct 30 2026: 0 submissions");
});

const weekStart = new Date(2026, 11, 28).getTime() / 1000;
const submittedAt = (month: number, day: number, hour = 0) => ({
  creationTimeSeconds: new Date(2026 + (month === 0 ? 1 : 0), month, day, hour).getTime() / 1000,
});

// Generated by Codex and not thoroughly checked for correctness.
test("seven unlabelled cells run Monday to Sunday across a year boundary and include only that week's submissions", () => {
  render(<ActiveDaysChart startTimeSeconds={weekStart} endTimeSeconds={new Date(2027, 0, 4).getTime() / 1000} submissions={[
    submittedAt(11, 27, 23),
    submittedAt(11, 28), submittedAt(11, 28, 12),
    submittedAt(0, 3, 23), submittedAt(0, 4),
  ]} />);
  const chart = screen.getByRole("group");
  const cells = within(chart).getAllByRole("img");
  expect(cells).toHaveLength(7);
  expect(cells.map((cell) => cell.getAttribute("aria-label"))).toEqual([
    "Mon Dec 28 2026: 2 submissions", "Tue Dec 29 2026: 0 submissions",
    "Wed Dec 30 2026: 0 submissions", "Thu Dec 31 2026: 0 submissions",
    "Fri Jan 01 2027: 0 submissions", "Sat Jan 02 2027: 0 submissions",
    "Sun Jan 03 2027: 1 submission",
  ]);
  expect(chart.textContent).toBe("");
  expect(cells[0].style.backgroundColor).toBe("rgb(149, 168, 221)");
  expect(cells[1].style.backgroundColor).toBe("rgb(199, 201, 212)");
});

// Generated by Codex and not thoroughly checked for correctness.
test("color intensity caps at five submissions and empty data still shows all seven days", () => {
  const view = render(<ActiveDaysChart startTimeSeconds={weekStart} endTimeSeconds={new Date(2027, 0, 4).getTime() / 1000} submissions={Array.from({ length: 8 }, () => submittedAt(11, 28))} />);
  expect(screen.getAllByRole("img")[0].style.backgroundColor).toBe("rgb(58, 74, 148)");
  view.rerender(<ActiveDaysChart startTimeSeconds={weekStart} endTimeSeconds={new Date(2027, 0, 4).getTime() / 1000} submissions={[]} />);
  expect(screen.getAllByRole("img").every((cell) => cell.getAttribute("aria-label")?.endsWith("0 submissions"))).toBe(true);
});

// Generated by Codex and not thoroughly checked for correctness.
test("hover and keyboard focus reveal the cell's date and submission count", async () => {
  render(<ActiveDaysChart startTimeSeconds={weekStart} endTimeSeconds={new Date(2027, 0, 4).getTime() / 1000} submissions={[submittedAt(11, 28)]} />);
  const monday = screen.getByRole("img", { name: "Mon Dec 28 2026: 1 submission" });
  fireEvent.mouseOver(monday);
  expect((await screen.findByRole("tooltip")).textContent).toBe("Mon Dec 28 2026: 1 submission");
  fireEvent.mouseOut(monday);
  const tuesday = screen.getByRole("img", { name: "Tue Dec 29 2026: 0 submissions" });
  fireEvent.focus(tuesday);
  expect((await screen.findByText("Tue Dec 29 2026: 0 submissions")).closest('[role="tooltip"]')).not.toBeNull();
});

// Generated by Codex and not thoroughly checked for correctness.
test.each([
  [ThemesType.LIGHT, "rgb(194, 205, 236)"],
  [ThemesType.DARK, "rgb(83, 97, 139)"],
] as const)("the current year stays visibly filled in theme %s when an earlier year has far more submissions", (themeType, lowActivityColor) => {
  frontend.theme = new Theme(themeType);
  vi.useFakeTimers();
  vi.setSystemTime(new Date(2026, 9, 31, 12));
  const submissions = [
    ...Array.from({ length: 10_000 }, () => ({ creationTimeSeconds: new Date(2023, 0, 1).getTime() / 1000 })),
    { creationTimeSeconds: new Date(2026, 9, 31, 10).getTime() / 1000 },
  ];
  render(<ActiveDaysChart period={SnapshotPeriod.CUSTOM} submissions={submissions} />);
  const cells = screen.getAllByRole("img");
  expect(cells).toHaveLength(4);
  const currentYear = screen.getByRole("img", { name: "Thu Jan 01 2026 – Sat Oct 31 2026: 1 submission · 1/304 active days" });
  expect(currentYear.style.backgroundColor).toBe(lowActivityColor);
  expect(currentYear.style.backgroundColor.startsWith("rgba")).toBe(false);
});
